        "zh-CN"
      ]
    },
    "enforce": {
      "type": "string",
      "title": "When a reply is not in Chinese",
      "description": "rewrite: ask Claude to say it again in Chinese, once (one extra turn). remind: show a notice and remind Claude with your next prompt.",
